#' Compute Feed Conversion Ratio (FCR) with Confidence Flags
#'
#' @description
#' Compute feed conversion ratio (FCR) from ADG and ADFI over the same body
#' weight stage, flag pigs whose values rely on extrapolation, and summarise
#' the traits.
#'
#' @param adg Result of [calc_adg()].
#' @param adfi Result of [calc_adfi()] computed from the same `adg`.
#' @param min_coverage Minimum share of stage days with recorded feed
#'   intake for `fcr_flag = "ok"`. Default: `min_coverage` of the QC
#'   settings (0.7).
#' @param verbose 0 (silent), 1 (summary, default) or 2 (details).
#'
#' @return An object of class `ppt_fcr` (a list):
#'   - `per_pig`: `adg` (g/d), `adfi` (g/d), `fcr`, `gf`, `adg_type`,
#'     `coverage`, `stage_days`, `start_weight`, `end_weight`, `fcr_flag`,
#'     `fcr_note`;
#'   - `daily`: the daily table of [calc_adfi()];
#'   - `summary`: numeric summary (`n`, `min`, `max`, `median`, `mean`,
#'     `sd`, `cv`) of the main traits, for all pigs, for pigs with
#'     `fcr_flag = "ok"` and, with a `breed` column, for each breed;
#'   - `by_bin`: one row per pig and body weight class of `bin_width` kg:
#'     feed (`feed_kg`), gain (`gain_kg`), segment `fcr`,
#'     `weight_coverage_kg` (span of recorded body weights in the class),
#'     `low_coverage` (inner class covered by less than
#'     `min_bin_coverage_kg`) and `fcr_out` (segment FCR outside
#'     `bin_fcr_limits`);
#'   - `removed`, `settings`.
#'
#' @details
#' With `method = "national"` in the QC settings ([qc_config()] preset
#' `"national"`), FCR follows the national procedure instead:
#' 1. daily weights over the test period (missing days interpolated
#'    linearly inside, predicted by a quadratic curve at the ends) and daily
#'    feed intake (missing days imputed by `impute_method`);
#' 2. days whose weight lies in `stage_range` are split into `bin_width` kg
#'    classes; a class with a weight gain below `bin_min_gain_kg` or an FCR
#'    outside `bin_fcr_limits` is removed, and a pig with a removed class
#'    between two kept ones is removed;
#' 3. cumulative feed intake over the kept days is regressed on body weight
#'    (pigs with R² <= `cfi_r2_min` are removed) and extended with that
#'    slope to the stage limits;
#' 4. FCR = (cumulative intake at the upper limit - at the lower limit) /
#'    stage width.
#'
#' `per_pig` then also has `cfi_start`, `cfi_end` (kg), `cfi_r2`,
#' `cfi_slope`, `weight_first`, `weight_last` (first and last kept daily
#' weight), `extrap_kg_start`, `extrap_kg_end` (kg extended by the
#' regression; more than `bin_width` gives `fcr_flag = "low_confidence"`),
#' `n_classes` and `n_classes_removed`; `by_bin` gives `removed` (reason or
#' `NA`) for each class. ADG and ADFI are those of [calc_adg()] and
#' [calc_adfi()].
#'
#' @seealso [calc_adg()], [calc_adfi()].
#' @export
#' @examples
#' visits <- prep_visits(nedap, verbose = 0)
#' adg <- calc_adg(clean_weight(visits, verbose = 0), verbose = 0)
#' adfi <- calc_adfi(visits, adg, verbose = 0)
#' fcr <- calc_fcr(adg, adfi)
#' head(fcr$per_pig[, .(responder, adg, adfi, fcr, fcr_flag, fcr_note)])
#' fcr$summary[group == "all"]
calc_fcr <- function(adg, adfi, min_coverage = adg$settings$min_coverage,
                     verbose = 1) {
  local_verbose(verbose)
  if (!inherits(adg, "ppt_adg")) {
    cli::cli_abort("{.arg adg} must be the result of {.fn calc_adg}.")
  }
  if (!inherits(adfi, "ppt_adfi")) {
    cli::cli_abort("{.arg adfi} must be the result of {.fn calc_adfi}.")
  }
  if (!identical(adg$settings$stage_range, adfi$settings$stage_range)) {
    cli::cli_abort("{.arg adg} and {.arg adfi} use different {.field stage_range}.")
  }
  if (identical(adg$settings$method, "national")) {
    return(calc_fcr_national(adg, adfi))
  }
  ppt_msg("FCR over {adg$settings$stage_range[1]}-{adg$settings$stage_range[2]} kg", "h1")

  a <- adg$per_pig[, intersect(c("responder", "location", "breed", "stage", "adg", "adg_type",
                                "stage_days", "start_weight", "end_weight", "weight_status",
                                "extrap_days_start", "extrap_days_end"), names(adg$per_pig)),
                   with = FALSE]
  f <- adfi$per_pig[, .(responder, adfi, coverage, n_extrap_start, n_extrap_end)]
  max_edge <- adg$settings$max_edge_extrap_days
  per_pig <- merge(a, f, by = "responder", all.x = TRUE)
  per_pig[, `:=`(fcr = adfi / adg, gf = adg / adfi)]

  notes <- character(nrow(per_pig))
  add_note <- function(cond, text) {
    cond <- cond %in% TRUE
    if (!any(cond)) return(invisible(NULL))
    text <- if (length(text) == 1L) rep(text, sum(cond)) else text[cond]
    notes[cond] <<- ifelse(nzchar(notes[cond]), paste(notes[cond], text, sep = "; "), text)
  }
  add_note(per_pig$adg_type == "partial", "ADG on part of the stage")
  add_note(per_pig$extrap_days_start > max_edge,
           sprintf("growth curve extrapolated %.0f d before the first weight", per_pig$extrap_days_start))
  add_note(per_pig$extrap_days_end > max_edge,
           sprintf("growth curve extrapolated %.0f d after the last weight", per_pig$extrap_days_end))
  add_note(per_pig$n_extrap_start > max_edge,
           sprintf("feed intake extrapolated for the first %d stage days", as.integer(per_pig$n_extrap_start)))
  add_note(per_pig$n_extrap_end > max_edge,
           sprintf("feed intake extrapolated for the last %d stage days", as.integer(per_pig$n_extrap_end)))
  add_note(per_pig$coverage < min_coverage,
           sprintf("feed intake recorded on %.0f%% of the stage", 100 * per_pig$coverage))
  add_note(per_pig$weight_status == "low_confidence", "weight data flagged")
  by_bin <- fcr_by_bin(adg, adfi, adg$settings)
  bin_notes <- by_bin[low_coverage == TRUE | fcr_out == TRUE, .(note = paste(
    c(if (any(low_coverage)) sprintf("weight records cover %.1f kg of %s-%s kg",
                                     weight_coverage_kg[low_coverage], weight_from[low_coverage], weight_to[low_coverage]),
      if (any(fcr_out)) sprintf("segment FCR %.2f outside %s-%s in %s-%s kg", fcr[fcr_out],
                                fcr_min[fcr_out], fcr_max[fcr_out], weight_from[fcr_out], weight_to[fcr_out])),
    collapse = "; ")), by = responder]
  m <- match(per_pig$responder, bin_notes$responder)
  add_note(!is.na(m), bin_notes$note[m])
  add_note(is.na(per_pig$fcr), "no FCR")
  per_pig[, `:=`(fcr_note = notes,
                 fcr_flag = data.table::fifelse(nzchar(notes), "low_confidence", "ok"))]
  per_pig[is.na(fcr), fcr_flag := NA_character_]
  per_pig[, weight_status := NULL]
  data.table::setcolorder(per_pig, intersect(c("responder", "location", "breed", "stage", "adg", "adfi",
                                     "fcr", "gf", "adg_type", "coverage", "stage_days",
                                     "start_weight", "end_weight", "fcr_flag", "fcr_note"), names(per_pig)))
  data.table::setorder(per_pig, location, responder)

  summary <- rbind(
    trait_summary(per_pig, "all"),
    trait_summary(per_pig[fcr_flag %in% "ok"], "ok")
  )
  if ("breed" %in% names(per_pig)) {
    for (b in sort(unique(stats::na.omit(per_pig$breed)))) {
      summary <- rbind(summary, trait_summary(per_pig[breed %in% b], paste("breed", b)))
    }
  }

  n_ok <- per_pig[fcr_flag %in% "ok", .N]
  n_low <- per_pig[fcr_flag %in% "low_confidence", .N]
  ppt_msg("FCR for {sum(!is.na(per_pig$fcr))} pig{?s}: {n_ok} ok, {n_low} low confidence", "info")
  s <- summary[group == "all" & trait == "fcr"]
  if (nrow(s) == 1L && s$n > 0) {
    ppt_msg("Mean FCR {sprintf('%.2f', s$mean)} (SD {sprintf('%.2f', s$sd)}), ADG {round(summary[group == 'all' & trait == 'adg', mean])} g/d, ADFI {round(summary[group == 'all' & trait == 'adfi', mean])} g/d", "success")
  }
  if (n_low > 0L) {
    why <- sort(table(unlist(strsplit(per_pig[fcr_flag %in% "low_confidence", fcr_note], "; "))), decreasing = TRUE)
    why <- unique(gsub("[0-9]+(\\.[0-9]+)?", "N", names(why)))
    ppt_msg("Low confidence because of: {paste(unique(why), collapse = ', ')}", "info", level = 2L)
  }

  new_ppt_result(per_pig = per_pig, daily = adfi$daily, removed = adfi$removed,
                 settings = adg$settings, class = "ppt_fcr") |>
    add_element(summary = summary, by_bin = by_bin)
}

# Feed intake, gain and FCR per body weight class of each pig.
# FCR by the national method (qc_config("national")):
# 1. daily weights (weighted means) of the test period, missing days
#    interpolated linearly inside and predicted by a quadratic curve at the
#    ends; daily feed intake from calc_adfi(), missing days imputed by the
#    national rule;
# 2. days whose weight lies in stage_range are split into bin_width classes;
#    a class whose weight gain is below bin_min_gain_kg, or whose FCR is
#    outside bin_fcr_limits, is removed; a pig with a removed (or missing)
#    class between two kept classes is removed;
# 3. cumulative feed intake over the kept days; it is regressed on body
#    weight (linear) - pigs with R2 <= cfi_r2_min are removed - and the
#    regression slope extends it from the first / last kept day to the
#    stage limits;
# 4. FCR = (CFI at the upper limit - CFI at the lower limit) / stage width.
calc_fcr_national <- function(adg, adfi) {
  qc <- adg$settings
  lo <- qc$stage_range[1L]
  hi <- qc$stage_range[2L]
  ppt_msg("FCR over {lo}-{hi} kg (national method: cumulative feed intake)", "h1")
  pigs <- adg$per_pig[!is.na(adg), responder]
  dly <- adg$daily[responder %in% pigs, .(responder, location, date, seq_days, weight, predicted)]
  feed <- adfi$daily[, .(responder, date, dfi, state)]

  one <- function(id) {
    d <- dly[responder == id]
    data.table::setorder(d, date)
    obs <- d[!is.na(weight)]
    if (nrow(obs) < 5L) return(list(error = "fewer than 5 daily weights"))
    days <- seq(min(obs$date), max(obs$date), by = 1)
    g <- data.table::data.table(responder = id, date = days)
    g[obs, on = "date", w_obs := i.weight]
    # weights: linear interpolation inside, quadratic prediction at the ends
    x <- as.numeric(g$date - min(g$date))
    ok <- !is.na(g$w_obs)
    g[, w := stats::approx(x[ok], w_obs[ok], xout = x)$y]
    if (anyNA(g$w)) {
      fit <- stats::lm(w_obs ~ x + I(x^2), data = data.frame(w_obs = g$w_obs[ok], x = x[ok]))
      miss <- is.na(g$w)
      g[miss, w := stats::predict(fit, newdata = data.frame(x = x[miss]))]
    }
    g[feed[responder == id], on = "date", `:=`(dfi = i.dfi, state = i.state)]
    g[, in_band := w >= lo & w <= hi]
    if (!any(g$in_band)) return(list(error = "no daily weight inside the stage"))
    # impute missing intake on the stage days
    dd <- g[, .(date, seq_days = as.integer(date - min(date)) + 1L, bw = w,
                in_stage = in_band, state = data.table::fifelse(state %in% c("org", "corr"), state, NA_character_),
                dfi_check = data.table::fifelse(state %in% c("org", "corr"), dfi, NA_real_))]
    dd <- impute_dfi_one_pig(dd, qc)
    g[, dfi := dd$dfi]
    st <- g[in_band == TRUE]
    if (anyNA(st$dfi)) return(list(error = "daily feed intake missing on stage days"))
    width <- qc$bin_width
    st[, weight_from := pmin(lo + floor((w - lo) / width) * width, hi - width)]
    bins <- st[, .(n_days = .N, w_first = w[1L], w_last = w[.N], feed_kg = sum(dfi) / 1000),
               by = weight_from]
    bins[, `:=`(weight_to = pmin(weight_from + width, hi), gain_kg = w_last - w_first)]
    bins[, fcr := data.table::fifelse(gain_kg > 0, feed_kg / gain_kg, NA_real_)]
    bins[, `:=`(fcr_min = NA_real_, fcr_max = NA_real_)]
    if (!is.null(qc$bin_fcr_limits)) {
      lim <- data.table::as.data.table(qc$bin_fcr_limits)
      bins[lim, on = "weight_from", `:=`(fcr_min = i.fcr_min, fcr_max = i.fcr_max)]
    }
    bins[, removed := data.table::fcase(
      gain_kg < qc$bin_min_gain_kg, sprintf("gain %.1f kg < %s kg", gain_kg, qc$bin_min_gain_kg),
      !is.na(fcr_min) & (is.na(fcr) | fcr < fcr_min | fcr > fcr_max),
      sprintf("class FCR %.2f outside %s-%s", fcr, fcr_min, fcr_max),
      default = NA_character_)]
    data.table::setorder(bins, weight_from)
    kept_bins <- bins[is.na(removed), weight_from]
    out_bins <- data.table::copy(bins)[, responder := id]
    if (length(kept_bins) == 0L) {
      return(list(error = "every weight class removed", bins = out_bins))
    }
    expected <- seq(min(kept_bins), max(kept_bins), by = width)
    if (!all(expected %in% kept_bins)) {
      gapb <- setdiff(expected, kept_bins)
      return(list(error = sprintf("weight class %s kg removed or missing between kept classes",
                                  paste0(gapb, "-", gapb + width, collapse = ", ")),
                  bins = out_bins))
    }
    k <- st[weight_from %in% kept_bins]
    data.table::setorder(k, date)
    k[, cfi := cumsum(dfi) / 1000]
    cf <- stats::lm(cfi ~ w, data = k)
    r2 <- summary(cf)$r.squared
    if (!is.finite(r2) || r2 <= qc$cfi_r2_min) {
      return(list(error = sprintf("R2 of cumulative feed on weight %.3f <= %s", r2, qc$cfi_r2_min),
                  bins = out_bins))
    }
    b <- unname(stats::coef(cf)[2L])
    first <- k[1L]
    last <- k[.N]
    cfi_lo <- first$cfi - b * (first$w - lo)
    cfi_hi <- last$cfi + b * (hi - last$w)
    list(per_pig = data.table::data.table(
      responder = id, fcr = (cfi_hi - cfi_lo) / (hi - lo),
      cfi_start = cfi_lo, cfi_end = cfi_hi, cfi_r2 = r2, cfi_slope = b,
      weight_first = first$w, weight_last = last$w,
      extrap_kg_start = max(0, first$w - lo), extrap_kg_end = max(0, hi - last$w),
      n_classes = length(kept_bins), n_classes_removed = sum(!is.na(bins$removed))),
      bins = out_bins)
  }
  res <- lapply(pigs, one)
  ok <- vapply(res, function(r) is.null(r$error), logical(1))
  pp <- data.table::rbindlist(lapply(res[ok], `[[`, "per_pig"))
  by_bin <- data.table::rbindlist(lapply(res, `[[`, "bins"), fill = TRUE)
  if (nrow(by_bin) > 0L) {
    data.table::setcolorder(by_bin, c("responder", "weight_from", "weight_to"))
    by_bin[, c("w_first", "w_last") := NULL]
  }
  bad <- data.table::data.table(responder = pigs[!ok],
                                reason = vapply(res[!ok], `[[`, "", "error"))

  a <- adg$per_pig[, intersect(c("responder", "location", "breed", "stage", "adg", "adg_type",
                                "stage_days", "start_weight", "end_weight"), names(adg$per_pig)),
                   with = FALSE]
  f <- adfi$per_pig[, .(responder, adfi, coverage)]
  per_pig <- merge(merge(a, f, by = "responder", all.x = TRUE), pp, by = "responder", all.x = TRUE)
  per_pig[, gf := 1 / fcr]
  max_edge <- qc$bin_width
  per_pig[, fcr_note := data.table::fcase(
    is.na(fcr), "no FCR",
    extrap_kg_start > max_edge | extrap_kg_end > max_edge,
    sprintf("cumulative feed extrapolated over %.0f kg", extrap_kg_start + extrap_kg_end),
    default = "")]
  per_pig[, fcr_flag := data.table::fcase(is.na(fcr), NA_character_,
                                          nzchar(fcr_note), "low_confidence", default = "ok")]
  data.table::setcolorder(per_pig, intersect(c("responder", "location", "breed", "stage", "adg", "adfi",
                                     "fcr", "gf", "adg_type", "coverage", "fcr_flag", "fcr_note"),
                                   names(per_pig)))
  data.table::setorder(per_pig, location, responder)
  loc <- per_pig[, .(responder, location)]
  removed <- rbind(adfi$removed,
                   new_removed(bad$responder, loc$location[match(bad$responder, loc$responder)],
                               "calc_fcr", bad$reason))
  summary <- rbind(trait_summary(per_pig, "all"), trait_summary(per_pig[fcr_flag %in% "ok"], "ok"))
  if ("breed" %in% names(per_pig)) {
    for (bb in sort(unique(stats::na.omit(per_pig$breed)))) {
      summary <- rbind(summary, trait_summary(per_pig[breed %in% bb], paste("breed", bb)))
    }
  }
  ppt_msg("FCR for {sum(!is.na(per_pig$fcr))} pig{?s}; {nrow(bad)} removed by the class and cumulative-feed checks",
          if (nrow(bad) > 0L) "warning" else "success")
  s <- summary[group == "all" & trait == "fcr"]
  if (nrow(s) == 1L && s$n > 0) {
    ppt_msg("Mean FCR {sprintf('%.2f', s$mean)} (SD {sprintf('%.2f', s$sd)})", "success")
  }
  new_ppt_result(per_pig = per_pig, daily = adfi$daily, removed = removed,
                 settings = qc, class = "ppt_fcr") |>
    add_element(summary = summary, by_bin = by_bin)
}

fcr_by_bin <- function(adg, adfi, qc) {
  lo <- qc$stage_range[1L]
  hi <- qc$stage_range[2L]
  width <- qc$bin_width
  cls <- function(w) lo + floor((w - lo) / width) * width
  st <- adfi$daily[in_stage == TRUE & !is.na(bw) & !is.na(dfi)]
  st[, weight_from := cls(bw)]
  st <- st[weight_from >= lo & weight_from < hi]
  bins <- st[, .(n_days = .N, n_observed_feed = sum(state %in% c("org", "corr")),
                 feed_kg = sum(dfi) / 1000, bw_min = min(bw), bw_max = max(bw)),
             by = .(responder, weight_from)]
  # gain over the days of the class (daily weights are mid-day values)
  bins[, gain_kg := data.table::fifelse(n_days > 1L, (bw_max - bw_min) * n_days / (n_days - 1L), NA_real_)]
  bins[, fcr := feed_kg / gain_kg]
  bins[, weight_to := pmin(weight_from + width, hi)]

  # how much of each class is covered by recorded body weights
  ob <- adg$daily[source == "observed" & !is.na(weight)]
  ob[, weight_from := cls(weight)]
  ob <- ob[weight_from >= lo & weight_from < hi]
  cov <- if (nrow(ob) > 0L) {
    ob[, .(weight_coverage_kg = max(weight) - min(weight)), by = .(responder, weight_from)]
  } else {
    data.table::data.table(responder = character(), weight_from = numeric(),
                           weight_coverage_kg = numeric())
  }
  bins <- merge(bins, cov, by = c("responder", "weight_from"), all.x = TRUE)
  bins[is.na(weight_coverage_kg), weight_coverage_kg := 0]
  rng <- if (nrow(cov) > 0L) {
    cov[, .(first_bin = min(weight_from), last_bin = max(weight_from)), by = responder]
  } else {
    data.table::data.table(responder = character(), first_bin = numeric(), last_bin = numeric())
  }
  bins <- merge(bins, rng, by = "responder", all.x = TRUE)
  bins[, inner := (weight_from > first_bin & weight_from < last_bin) %in% TRUE]
  bins[, low_coverage := inner & weight_coverage_kg < qc$min_bin_coverage_kg]

  bins[, `:=`(fcr_min = NA_real_, fcr_max = NA_real_)]
  if (!is.null(qc$bin_fcr_limits)) {
    lim <- data.table::as.data.table(qc$bin_fcr_limits)
    bins[lim, on = "weight_from", `:=`(fcr_min = i.fcr_min, fcr_max = i.fcr_max)]
  }
  bins[, fcr_out := !is.na(fcr) & !is.na(fcr_min) & (fcr < fcr_min | fcr > fcr_max)]
  bins[, c("bw_min", "bw_max", "first_bin", "last_bin") := NULL]
  data.table::setcolorder(bins, c("responder", "weight_from", "weight_to", "n_days",
                                  "n_observed_feed", "feed_kg", "gain_kg", "fcr",
                                  "weight_coverage_kg", "inner", "low_coverage",
                                  "fcr_min", "fcr_max", "fcr_out"))
  data.table::setorder(bins, responder, weight_from)
  bins[]
}

trait_summary <- function(p, group) {
  traits <- c("adg", "adfi", "fcr", "gf", "stage_days", "start_weight", "end_weight")
  out <- data.table::rbindlist(lapply(traits, function(tr) {
    x <- p[[tr]]
    x <- x[!is.na(x)]
    n <- length(x)
    data.table::data.table(
      group = group, trait = tr, n = n,
      min = if (n) min(x) else NA_real_,
      max = if (n) max(x) else NA_real_,
      median = if (n) stats::median(x) else NA_real_,
      mean = if (n) mean(x) else NA_real_,
      sd = if (n > 1L) stats::sd(x) else NA_real_
    )
  }))
  out[, cv := sd / mean]
  out[]
}
